  // response, not a success response, silence. Per
  // @salesforce/pwa-kit-runtime's own build-remote-server.js, the rejection
  // itself is caught and logged by the framework's global handler (so the
  // server process survives — confirmed by reading that source directly),
  // but nothing in that path ever touches this specific Express response.
  // The shopper's request is left to run out MRT's own 20s/16s execution
  // ceiling and receive a generic, uninformative 502.
  expect(magicLinkRes.send).not.toHaveBeenCalled();
  expect(magicLinkRes.json).not.toHaveBeenCalled();
  expect(magicLinkRes.status).not.toHaveBeenCalled();
});

