import { describe, test, expect, vi, beforeEach } from 'vitest';

vi.mock('@salesforce/pwa-kit-runtime/utils/ssr-config', () => ({
  getConfig: vi.fn(),
}));

import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
import { paymentMetadataHandler } from './paymentMetadata';
import { sendMagicLinkEmail } from './marketingCloud';
import type { SsrReq, SsrRes } from './types';

type MockRes = SsrRes & { statusCode?: number; body?: unknown };

function createMockRes(): MockRes {
  const res = {} as MockRes;
  res.status = vi.fn().mockImplementation((code: number) => {
    res.statusCode = code;
    return res;
  });
  res.json = vi.fn().mockImplementation((data: unknown) => {
    res.body = data;
    return res;
  });
  res.send = vi.fn().mockImplementation((data: unknown) => {
    res.body = data;
    return res;
  });
  res.setHeader = vi.fn().mockReturnValue(res);
  res.set = vi.fn().mockReturnValue(res);
  return res;
}

function createMockReq(): SsrReq {
  return {
    protocol: 'https',
    body: { email_id: 'shopper@example.com', token: 'reset-token' },
    get: vi.fn().mockReturnValue('zimmermann.com'),
    params: {},
    query: {},
    headers: {},
  };
}

const PAYMENTS_URL = 'https://payments.example.demandware.net/metadata';

/**
 * SFCC-681 as-is baseline evidence (see .docs/temp/tsd-architecture.md §12.1 and
 * overrides/app/ssr/connectionPools.ts). These use the real handler functions, not
 * stand-ins, to demonstrate today's shared-process failure isolation gap and give
 * the TSD's Options Analysis / Risks sections real, reproducible evidence instead
 * of an assertion. Every fetch here is mocked; nothing calls a real network endpoint.
 */
describe('SSR shared-process blast radius (SFCC-681 as-is baseline)', () => {
  beforeEach(() => {
    vi.stubEnv('MARKETING_CLOUD_CLIENT_ID', 'test-client-id');
    vi.stubEnv('MARKETING_CLOUD_CLIENT_SECRET', 'test-client-secret');
    vi.stubEnv('MARKETING_CLOUD_SUBDOMAIN', 'test-subdomain');

    vi.mocked(getConfig).mockReturnValue({
      app: {
        sfPayments: { metadataUrl: PAYMENTS_URL },
        login: { resetPassword: { landingPath: '/reset-password' }, passwordless: {} },
      },
    } as ReturnType<typeof getConfig>);

    vi.stubGlobal(
      'fetch',
      vi.fn((input: string | URL) => {
        const href = String(input);
        if (href.includes('payments.example.demandware.net')) {
          return Promise.resolve({ ok: true, json: () => Promise.resolve({ paymentMethodTypes: {} }) } as Response);
        }
        if (href.includes('auth.marketingcloudapis.com')) {
          return Promise.resolve({ ok: true, json: () => Promise.resolve({ access_token: 'fake-token' }) } as Response);
        }
        if (href.includes('rest.marketingcloudapis.com')) {
          // Simulates Marketing Cloud's send-email endpoint being down — the
          // token exchange above succeeds, only the send call fails.
          return Promise.resolve({ ok: false, status: 503 } as Response);
        }
        return Promise.reject(new Error(`Unexpected fetch in test: ${href}`));
      }),
    );
  });

  test('Test 1 — a failing integration silently discards an unrelated, already-succeeded one', async () => {
    const paymentsRes = createMockRes();
    const magicLinkRes = createMockRes();

    const paymentsCall = paymentMetadataHandler({}, paymentsRes);
    const magicLinkCall = sendMagicLinkEmail(createMockReq(), magicLinkRes, '/reset-password', 'reset-template');

    // Ground truth, checked independently of one another: payment metadata
    // genuinely succeeds; the magic-link send genuinely rejects uncaught —
    // sendMagicLinkEmail has no try/catch around its Marketing Cloud call,
    // unlike paymentMetadataHandler and jwksCaching, which both catch their
    // own fetch failures and turn them into HTTP error responses.
    const [paymentsOutcome, magicLinkOutcome] = await Promise.allSettled([paymentsCall, magicLinkCall]);
    expect(paymentsOutcome.status).toBe('fulfilled');
    expect(magicLinkOutcome.status).toBe('rejected');
    expect(paymentsRes.body).toEqual(expect.objectContaining({ paymentMethodTypes: {} }));

    // What a normal caller aggregating "I need both of these" via Promise.all
    // actually experiences today: total failure. The successful payment data
    // was sitting right there, computed, one line above — Promise.all discards
    // it the moment the sibling call rejects, with no way for the caller to
    // recover it.
    const paymentsRes2 = createMockRes();
    const magicLinkRes2 = createMockRes();
    await expect(
      Promise.all([
        paymentMetadataHandler({}, paymentsRes2),
        sendMagicLinkEmail(createMockReq(), magicLinkRes2, '/reset-password', 'reset-template'),
      ]),
    ).rejects.toThrow(/Marketing Cloud/i);
  });

  test('Test 3 — the same gap has no region boundary: it is scoped to the process, not the customer', async () => {
    // Same two real functions as Test 1, different narrative: paymentMetadataHandler
    // stands in for an AU checkout page (AU never touches Marketing Cloud on this
    // path); sendMagicLinkEmail stands in for a completely unrelated US shopper's
    // password-reset request, in flight on the same process at the same time.
    // Nothing in the code scopes the failure to the customer or region that
    // triggered it — only which Node process happened to be handling both.
    const auPaymentsRes = createMockRes();
    const usMagicLinkRes = createMockRes();

    await expect(
      Promise.all([
        paymentMetadataHandler({}, auPaymentsRes),
        sendMagicLinkEmail(createMockReq(), usMagicLinkRes, '/reset-password', 'reset-template'),
      ]),
    ).rejects.toThrow(/Marketing Cloud/i);

    // The AU-scoped call's own fetch still genuinely succeeded in isolation —
    // re-run it alone to prove the failure above was never a payments-side problem.
    const auOnlyRes = createMockRes();
    await paymentMetadataHandler({}, auOnlyRes);
    expect(auOnlyRes.body).toEqual(expect.objectContaining({ paymentMethodTypes: {} }));
  });

  test('Test 2 — a synchronous, CPU-bound task blocks every other concurrent request on the same process', async () => {
    // No mocking here — this is a genuine property of Node's single-threaded
    // event loop, not something specific to any one integration's code, and not
    // something undici connection pools can fix (pools govern network sockets,
    // not who holds the JS thread).
    let fastResolvedAt = 0;
    const start = Date.now();

    const fastRequest = Promise.resolve().then(() => {
      fastResolvedAt = Date.now();
    });

    const BLOCK_MS = 200;
    const blockUntil = Date.now() + BLOCK_MS;
    while (Date.now() < blockUntil) {
      // Deliberately busy-wait — stands in for a heavy synchronous operation
      // (a large JSON.parse, a slow regex) inside some integration's handler.
    }

    await fastRequest;
    const fastRequestDelay = fastResolvedAt - start;

    // The "fast" request should resolve near-instantly. Instead it's held
    // hostage behind the blocking work for the full BLOCK_MS, because they
    // share one event loop — there is no infrastructure fix for this; it's an
    // accepted trade-off of the single-app model, mitigated only by a coding
    // rule (never block synchronously in an integration handler), not wiring.
    expect(fastRequestDelay).toBeGreaterThanOrEqual(BLOCK_MS - 5);
  });
});

