test('Test 1b — the real ssr.js call shape never sends a response to the shopper on failure', async () => {
  const magicLinkRes = createMockRes();

  // The real ssr.js route handlers never attach a .catch() or await this
  // call, so the only thing standing between this rejection and an
  // undetected failure is @salesforce/pwa-kit-runtime's own global handler
  // (build-remote-server.js:1794 — process.on('unhandledRejection',
  // catchAndLog)). Registering the same kind of listener here reproduces
  // that exact real-world safety net rather than an artificial one, and
  // lets this test both prove the rejection genuinely goes unhandled by
  // any application code and avoid Vitest reporting it as a stray,
  // run-failing error outside the test itself.
  let capturedRejection: unknown;
  const onUnhandledRejection = (reason: unknown) => {
    capturedRejection = reason;
  };
  process.once('unhandledRejection', onUnhandledRejection);

  try {
    // Reproduces the exact shape of the real call sites in ssr.js (the
    // passwordless-login and reset-password routes): sendMagicLinkEmail is
    // invoked inside a .then() callback and its promise is never returned,
    // awaited, or chained to anything — unlike Test 1 above, which awaits
    // it directly to test the function's own behaviour in isolation. This
    // is what actually ships today, not a hypothetical calling pattern.
    Promise.resolve().then(() => {
      sendMagicLinkEmail(createMockReq(), magicLinkRes, '/reset-password', 'reset-template');
    });

    // Give the orphaned rejection every chance to fully settle. Several
    // chained awaits happen inside sendMagicLinkEmail before it actually
    // rejects, and Node's own unhandled-rejection detection runs at the end
    // of the microtask queue — 50ms of real time is generously more than
    // enough margin for a chain that in practice resolves in well under a
    // millisecond.
    await new Promise((resolve) => setTimeout(resolve, 50));

    // Proves this genuinely becomes a process-level unhandled rejection —
    // exactly what pwa-kit-runtime's own catchAndLog listens for in the
    // real MRT-deployed server — and that it's specifically this failure,
    // not something unrelated.
    expect(capturedRejection).toBeInstanceOf(Error);
    expect((capturedRejection as Error).message).toMatch(/Marketing Cloud/i);

    // The other half of the finding: nobody ever tells the shopper
    // anything — not an error response, not a success response, silence.
    // The framework's handler only logs; nothing in that path ever touches
    // this specific Express response. The shopper's request is left to run
    // out MRT's own 20s/16s execution ceiling and receive a generic,
    // uninformative 502.
    expect(magicLinkRes.send).not.toHaveBeenCalled();
    expect(magicLinkRes.json).not.toHaveBeenCalled();
    expect(magicLinkRes.status).not.toHaveBeenCalled();
  } finally {
    process.removeListener('unhandledRejection', onUnhandledRejection);
  }
});

