210	    // something undici connection pools can fix (pools govern network sockets,
211	    // not who holds the JS thread).
212	    let fastResolvedAt = 0;
213	    const start = Date.now();
214	
215	    const fastRequest = Promise.resolve().then(() => {
216	      fastResolvedAt = Date.now();
217	    });
218	
219	    const BLOCK_MS = 200;
220	    const blockUntil = Date.now() + BLOCK_MS;
221	    while (Date.now() < blockUntil) {
