/**
 * Empirical check: does Node's built-in undici (backing global fetch) isolate
 * connections per origin by default, and are per-origin connections bounded?
 *
 * Uses ONLY global fetch and node:http, so it measures the exact runtime our
 * SSR code uses. No undici import: the npm `undici` package keeps its own
 * global dispatcher, separate from Node's internal one, so importing it would
 * inspect the wrong thing.
 */
import http from 'node:http';

const listen = (server) =>
  new Promise((resolve) => server.listen(0, '127.0.0.1', () => resolve(server.address().port)));

const SLOW_MS = 1500;

// Track how many sockets each server sees concurrently: this reveals whether
// undici bounds connections per origin.
let slowConcurrent = 0;
let slowPeakConcurrent = 0;

const slowServer = http.createServer((req, res) => {
  slowConcurrent += 1;
  slowPeakConcurrent = Math.max(slowPeakConcurrent, slowConcurrent);
  setTimeout(() => {
    slowConcurrent -= 1;
    res.writeHead(200).end('slow');
  }, SLOW_MS);
});

const fastServer = http.createServer((req, res) => {
  res.writeHead(200).end('fast');
});

const slowPort = await listen(slowServer);
const fastPort = await listen(fastServer);
const SLOW = `http://127.0.0.1:${slowPort}/`;
const FAST = `http://127.0.0.1:${fastPort}/`;

console.log('node', process.version);

// --- 1. Baseline: fast origin, no competing load -------------------------
{
  const t = Date.now();
  await fetch(FAST).then((r) => r.text());
  console.log('\nbaseline  | fast origin, no load   :', Date.now() - t, 'ms');
}

// --- 2. Saturate the SLOW origin, then hit the FAST origin ---------------
const FLOOD = 100;
const floodStart = Date.now();
const flood = Array.from({ length: FLOOD }, () => fetch(SLOW).then((r) => r.text()));

// Let the flood get genuinely in flight before measuring.
await new Promise((r) => setTimeout(r, 300));

const tFast = Date.now();
await fetch(FAST).then((r) => r.text());
const fastUnderLoad = Date.now() - tFast;
console.log(`under load| fast origin (${FLOOD} slow in flight):`, fastUnderLoad, 'ms');

// --- 3. Same-origin contention -------------------------------------------
const tSlow = Date.now();
await fetch(SLOW).then((r) => r.text());
const slowUnderLoad = Date.now() - tSlow;
console.log('under load| slow origin (same origin) :', slowUnderLoad, `ms (server delay ${SLOW_MS}ms)`);

await Promise.all(flood);
console.log('          | all', FLOOD, 'slow requests done in', Date.now() - floodStart, 'ms');
console.log('          | peak concurrent sockets at slow origin:', slowPeakConcurrent);

// --- 4. Verdict -----------------------------------------------------------
console.log('\n--- VERDICT ---');
console.log(
  fastUnderLoad < 300
    ? `[A] CROSS-ORIGIN ISOLATED by default. Unrelated origin served in ${fastUnderLoad}ms while ${FLOOD} requests were stalled on another origin.`
    : `[A] CROSS-ORIGIN STARVATION. Unrelated origin delayed to ${fastUnderLoad}ms.`,
);
console.log(
  slowPeakConcurrent >= FLOOD
    ? `[B] PER-ORIGIN CONNECTIONS UNBOUNDED: ${slowPeakConcurrent} concurrent sockets opened to one origin (no default cap).`
    : `[B] PER-ORIGIN CAP IN EFFECT: peaked at ${slowPeakConcurrent} concurrent sockets, so undici bounds connections per origin.`,
);

slowServer.close();
fastServer.close();

