const fastServer = http.createServer((req, res) => {
  res.writeHead(200).end('fast');
});

const slowPort = await listen(slowServer);
const fastPort = await listen(fastServer);
const SLOW = `http://127.0.0.1:${slowPort}/`;
const FAST = `http://127.0.0.1:${fastPort}/`;

// --- 1. Inspect the global dispatcher's defaults -------------------------
const agent = getGlobalDispatcher();
const opts = agent[Object.getOwnPropertySymbols(agent).find((s) => s.description === 'options')] ?? {};
console.log('--- global dispatcher ---');
console.log('constructor          :', agent.constructor.name);
console.log('connections (per origin):', opts.connections === undefined ? '(not set)' : opts.connections);
console.log('connectTimeout       :', opts.connect?.timeout ?? '(default)');
console.log('headersTimeout       :', opts.headersTimeout ?? '(default)');
console.log('bodyTimeout          :', opts.bodyTimeout ?? '(default)');

// --- 2. Baseline: fast origin with no competing load ---------------------
{
  const t = Date.now();
  await fetch(FAST);
  console.log('\n--- baseline ---');
  console.log('fast origin, no load :', Date.now() - t, 'ms');
}

// --- 3. Saturate the SLOW origin, then hit the FAST origin ---------------
const FLOOD = 100;
console.log(`\n--- flooding slow origin with ${FLOOD} concurrent requests ---`);
const floodStart = Date.now();
const flood = Array.from({ length: FLOOD }, () => fetch(SLOW).then((r) => r.text()));

// Give the flood a moment to actually be in flight before measuring.
await new Promise((r) => setTimeout(r, 250));

const t = Date.now();
await fetch(FAST);
const fastUnderLoad = Date.now() - t;
console.log('fast origin, under load:', fastUnderLoad, 'ms');

// --- 4. Same-origin contention: another request to the SLOW origin -------
const t2 = Date.now();
await fetch(SLOW).then((r) => r.text());
const slowUnderLoad = Date.now() - t2;
console.log('slow origin, under load:', slowUnderLoad, 'ms', `(server delay is ${SLOW_MS}ms)`);

await Promise.all(flood);
console.log('all', FLOOD, 'slow requests done in', Date.now() - floodStart, 'ms');

// --- 5. Verdict ----------------------------------------------------------
console.log('\n--- verdict ---');
console.log(
  fastUnderLoad < 250
    ? `CROSS-ORIGIN ISOLATED by default: unrelated origin unaffected (${fastUnderLoad}ms).`
    : `CROSS-ORIGIN STARVATION: unrelated origin delayed to ${fastUnderLoad}ms.`,
);
console.log(
  slowUnderLoad < SLOW_MS * 1.6
