/**
 * How long does global fetch wait on an upstream that accepts the TCP
 * connection but never sends a response?
 *
 * The threshold that matters is MRT's own execution ceiling: 20s production /
 * 16s non-production. If undici's default exceeds that, MRT kills the request
 * before undici does, and the shopper gets a generic 502 rather than the
 * integration failing cleanly.
 */
import http from 'node:http';

const MRT_PROD_CEILING_MS = 20_000;

// Accepts the connection, then holds it open forever without responding.
const blackHole = http.createServer(() => {
  /* deliberately never respond */
});

const port = await new Promise((resolve) =>
  blackHole.listen(0, '127.0.0.1', () => resolve(blackHole.address().port)),
);

console.log('node', process.version);
console.log(`probing default response timeout, capped at MRT's ${MRT_PROD_CEILING_MS / 1000}s production ceiling...\n`);

const start = Date.now();
const result = await Promise.race([
  fetch(`http://127.0.0.1:${port}/`)
    .then(() => ({ kind: 'responded' }))
    .catch((err) => ({ kind: 'rejected', message: err.message, cause: err.cause?.message })),
  new Promise((resolve) => setTimeout(() => resolve({ kind: 'still-waiting' }), MRT_PROD_CEILING_MS)),
]);
const elapsed = Date.now() - start;

if (result.kind === 'still-waiting') {
  console.log(`RESULT: fetch was STILL WAITING after ${elapsed}ms.`);
  console.log(`         undici's default timeout exceeds MRT's ${MRT_PROD_CEILING_MS / 1000}s production ceiling.`);
  console.log('         => MRT terminates the request first; the shopper gets a generic 502.');
  console.log('         => An explicit per-origin bodyTimeout is what makes the integration fail cleanly instead.');
} else if (result.kind === 'rejected') {
  console.log(`RESULT: fetch rejected after ${elapsed}ms -> ${result.message}${result.cause ? ` (${result.cause})` : ''}`);
  console.log(`         default timeout is BELOW MRT's ceiling, so undici fails first.`);
} else {
  console.log(`RESULT: unexpectedly got a response after ${elapsed}ms.`);
}

blackHole.close();
process.exit(0);

