import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';

vi.mock('@salesforce/pwa-kit-runtime/utils/ssr-config', () => ({
  getConfig: vi.fn(),
}));

import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
import { paymentMetadataHandler } from './paymentMetadata';
import { sendMagicLinkEmail } from './marketingCloud';
import type { SsrReq, SsrRes } from './types';

const PAYMENTS_URL = 'https://payments.example.demandware.net/metadata';

/** Duration of the deliberate synchronous block used to occupy the event loop. */
const BLOCK_MS = 200;
/** Allowance for timer resolution when asserting on wall-clock durations. */
const TIMER_TOLERANCE_MS = 5;
/** Upper bound on how long to wait for Node to report an unhandled rejection. */
const REJECTION_SETTLE_TIMEOUT_MS = 1_000;

type MockRes = SsrRes & { statusCode?: number; body?: unknown };

function createMockRes(): MockRes {
  // Built incrementally: every member of SsrRes is assigned immediately below,
  // so the object is complete before it is returned.
  const res = {} as MockRes;
  res.status = vi.fn().mockImplementation((code: number) => {
    res.statusCode = code;
    return res;
  });
  res.json = vi.fn().mockImplementation((data: unknown) => {
    res.body = data;
    return res;
  });
  res.send = vi.fn().mockImplementation((data: unknown) => {
    res.body = data;
    return res;
  });
  res.setHeader = vi.fn().mockReturnValue(res);
  res.set = vi.fn().mockReturnValue(res);
  return res;
}

function createMockReq(): SsrReq {
  return {
    protocol: 'https',
    body: { email_id: 'shopper@example.com', token: 'reset-token' },
    get: vi.fn().mockReturnValue('zimmermann.com'),
    params: {},
    query: {},
    headers: {},
  };
}

/**
 * As-is baseline evidence for SFCC-681 (TSD-SFCC-681, "MRT Application Topology").
 *
 * These exercise the real SSR handler functions rather than stand-ins, so the TSD's
 * Problem Statement and Options Analysis rest on reproducible evidence rather than
 * assertion.
 *
 * They document CURRENT behaviour. The first two are expected to change once the
 * safeguards in the TSD's §5 are implemented, and should then be updated to assert
 * the fixed behaviour rather than deleted. The third documents a permanent property
 * of any single-process model and is expected to keep passing unchanged.
 *
 * Every fetch is mocked; nothing here contacts a real network endpoint.
 */
describe('SSR shared-process blast radius (SFCC-681 as-is baseline)', () => {
  beforeEach(() => {
    vi.stubEnv('MARKETING_CLOUD_CLIENT_ID', 'test-client-id');
    vi.stubEnv('MARKETING_CLOUD_CLIENT_SECRET', 'test-client-secret');
    vi.stubEnv('MARKETING_CLOUD_SUBDOMAIN', 'test-subdomain');

    // getConfig returns the full PWA Kit runtime config; only the fields these two
    // handlers actually read are stubbed here.
    vi.mocked(getConfig).mockReturnValue({
      app: {
        sfPayments: { metadataUrl: PAYMENTS_URL },
        login: { resetPassword: { landingPath: '/reset-password' }, passwordless: {} },
      },
    } as ReturnType<typeof getConfig>);

    vi.stubGlobal(
      'fetch',
      vi.fn((input: string | URL) => {
        const href = String(input);
        // Each branch stubs only the Response members the handlers touch: ok, status, json.
        if (href.includes('payments.example.demandware.net')) {
          return Promise.resolve({ ok: true, json: () => Promise.resolve({ paymentMethodTypes: {} }) } as Response);
        }
        if (href.includes('auth.marketingcloudapis.com')) {
          return Promise.resolve({ ok: true, json: () => Promise.resolve({ access_token: 'fake-token' }) } as Response);
        }
        if (href.includes('rest.marketingcloudapis.com')) {
          // Marketing Cloud's send-email endpoint is down. The token exchange above
          // still succeeds, so only the send call fails.
          return Promise.resolve({ ok: false, status: 503 } as Response);
        }
        return Promise.reject(new Error(`Unexpected fetch in test: ${href}`));
      }),
    );
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    vi.unstubAllEnvs();
    vi.clearAllMocks();
  });

  test('an aggregating caller loses a successful result when a sibling integration rejects', async () => {
    const paymentsRes = createMockRes();
    const magicLinkRes = createMockRes();

    const paymentsCall = paymentMetadataHandler({}, paymentsRes);
    const magicLinkCall = sendMagicLinkEmail(createMockReq(), magicLinkRes, '/reset-password', 'reset-template');

    // Ground truth, established independently of one another: payment metadata
    // genuinely succeeds, and the magic-link send genuinely rejects uncaught.
    // sendMagicLinkEmail has no try/catch around its Marketing Cloud call, unlike
    // paymentMetadataHandler and jwksCaching, which both catch their own fetch
    // failures and convert them into HTTP error responses.
    const [paymentsOutcome, magicLinkOutcome] = await Promise.allSettled([paymentsCall, magicLinkCall]);
    expect(paymentsOutcome.status).toBe('fulfilled');
    expect(magicLinkOutcome.status).toBe('rejected');
    expect(paymentsRes.body).toEqual(expect.objectContaining({ paymentMethodTypes: {} }));

    // What a caller aggregating "I need both of these" experiences today. The
    // payment data was computed successfully, as proven above, but Promise.all
    // discards it the moment its sibling rejects, leaving the caller no way to
    // recover it.
    const paymentsRes2 = createMockRes();
    const magicLinkRes2 = createMockRes();
    await expect(
      Promise.all([
        paymentMetadataHandler({}, paymentsRes2),
        sendMagicLinkEmail(createMockReq(), magicLinkRes2, '/reset-password', 'reset-template'),
      ]),
    ).rejects.toThrow(/Marketing Cloud/i);
  });

  test('the shipped route shape leaves the request unanswered when its integration fails', async () => {
    const magicLinkRes = createMockRes();

    // The real ssr.js route handlers never await or catch this call, so the only
    // thing between the rejection and an undetected failure is pwa-kit-runtime's
    // own global handler (build-remote-server.js registers process.on(
    // 'unhandledRejection', catchAndLog), which logs and nothing more).
    // Registering an equivalent listener here reproduces that real safety net,
    // lets the test assert the rejection genuinely goes unhandled by application
    // code, and stops Vitest reporting it as a stray run-failing error.
    let capturedRejection: unknown;
    const onUnhandledRejection = (reason: unknown) => {
      capturedRejection = reason;
    };
    process.once('unhandledRejection', onUnhandledRejection);

    try {
      // Reproduces the exact shape of the shipped call sites in ssr.js: the
      // passwordless-login and reset-password routes both invoke
      // sendMagicLinkEmail inside a .then() callback without returning, awaiting
      // or chaining it. `void` marks the promises as deliberately unobserved for
      // the linter only; it attaches no handler and leaves the orphaned-promise
      // behaviour under test unchanged.
      void Promise.resolve().then(() => {
        void sendMagicLinkEmail(createMockReq(), magicLinkRes, '/reset-password', 'reset-template');
      });

      // Node reports unhandled rejections on a macrotask boundary, so poll rather
      // than sleeping for a fixed duration.
      await vi.waitFor(
        () => {
          expect(capturedRejection).toBeInstanceOf(Error);
        },
        { timeout: REJECTION_SETTLE_TIMEOUT_MS, interval: 10 },
      );
      expect((capturedRejection as Error).message).toMatch(/Marketing Cloud/i);

      // The other half of the finding: the shopper is told nothing at all. The
      // framework's handler only logs, and nothing in that path touches this
      // response. The request is left to run out MRT's execution ceiling and
      // return a generic 502.
      // eslint-disable-next-line @typescript-eslint/unbound-method -- plain vi.fn() mocks with no `this` dependency; standard Vitest call-count assertion.
      expect(magicLinkRes.send).not.toHaveBeenCalled();
      // eslint-disable-next-line @typescript-eslint/unbound-method -- see above
      expect(magicLinkRes.json).not.toHaveBeenCalled();
      // eslint-disable-next-line @typescript-eslint/unbound-method -- see above
      expect(magicLinkRes.status).not.toHaveBeenCalled();
    } finally {
      process.removeListener('unhandledRejection', onUnhandledRejection);
    }
  });

  test('a synchronous CPU-bound operation blocks unrelated concurrent work', async () => {
    // Nothing is mocked here. This is a property of Node's single-threaded event
    // loop rather than of any integration's code, and it is not addressable by
    // connection pools, which govern sockets rather than who holds the JS thread.
    // It therefore documents a permanent trade-off of the single-application
    // model rather than a defect to be fixed.
    let fastResolvedAt = 0;
    const start = Date.now();

    const fastRequest = Promise.resolve().then(() => {
      fastResolvedAt = Date.now();
    });

    const blockUntil = Date.now() + BLOCK_MS;
    while (Date.now() < blockUntil) {
      // Busy-wait, standing in for a heavy synchronous operation such as a large
      // JSON.parse or an expensive regex inside an integration handler.
    }

    await fastRequest;
    const fastRequestDelay = fastResolvedAt - start;

    // The fast work should resolve almost immediately. Instead it waits out the
    // entire blocking operation, because both share one event loop.
    expect(fastRequestDelay).toBeGreaterThanOrEqual(BLOCK_MS - TIMER_TOLERANCE_MS);
  });
});

